import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Bgcaomt7.js";var i=JSON.parse(`{"title":"Writing Agent Skills","description":"How to add or change a skill in @warp-drive/memory-alpha so coding agents find and follow it, including the routing tables, file rules, and checks.","frontmatter":{"title":"Writing Agent Skills","description":"How to add or change a skill in @warp-drive/memory-alpha so coding agents find and follow it, including the routing tables, file rules, and checks."},"headers":[],"relativePath":"guides/contributing/writing-documentation/writing-agent-skills.md","filePath":"guides/contributing/writing-documentation/writing-agent-skills.md"}`),a={name:`guides/contributing/writing-documentation/writing-agent-skills.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="writing-agent-skills" tabindex="-1">Writing Agent Skills <a class="header-anchor" href="#writing-agent-skills" aria-label="Permalink to “Writing Agent Skills”">​</a></h1><p>How to add or change a skill in <a href="https://github.com/warp-drive-data/warp-drive/blob/main/warp-drive-packages/memory-alpha/README.md" target="_blank" rel="noreferrer"><code>@warp-drive/memory-alpha</code></a>, the package of plain-markdown instructions that AI coding agents read when they work in this repo or in an app that depends on <strong><em>Warp</em>Drive</strong>. The same files are published for humans at <a href="/pr-preview/pr-11217/skills/">/skills</a>.</p><h2 id="audience" tabindex="-1">Audience <a class="header-anchor" href="#audience" aria-label="Permalink to “Audience”">​</a></h2><p>Of the <a href="./#know-your-audience">audiences</a> our documentation serves, a skill has two: the coding agent that will follow it, and the human who opens the published copy to see what agents are being told. Write for the agent. It has the repo in front of it and no conversation history, so give it the rule, the reason, and the exact place to look, and nothing it can read for itself. If the skill is in <code>skills/contributors/</code>, assume the agent is working inside this repo and knows its layout. If it is in a consumer directory such as <code>skills/schemas/</code> or <code>skills/requests/</code>, assume the agent is in an app that depends on <strong><em>Warp</em>Drive</strong> and knows only the public API.</p><h2 id="how-agents-reach-a-skill" tabindex="-1">How agents reach a skill <a class="header-anchor" href="#how-agents-reach-a-skill" aria-label="Permalink to “How agents reach a skill”">​</a></h2><p>Agents do not browse the package. Each agent surface in the repo (<code>AGENTS.md</code>, which <code>CLAUDE.md</code> and <code>GEMINI.md</code> import, plus the Copilot and Cursor pointer files) tells the agent to open one routing table and read only the row that matches its task:</p><ul><li><code>skills/contributors/index.md</code> routes agents contributing to <strong><em>Warp</em>Drive</strong> itself.</li><li><code>skills/index.md</code> routes agents consuming <code>@warp-drive/*</code> packages in an app.</li></ul><p>A skill that is not in the right table does not exist as far as agents are concerned. Adding a skill therefore always means touching four files in its directory: the skill itself, <code>index.md</code> (the agent-facing table), <code>overview.md</code> (the same table with links, published in place of <code>index.md</code> on the website), and <code>_meta.json</code> (sidebar title and order for the website). Miss the <code>overview.md</code> row and the website&#39;s table lacks the skill; miss the <code>_meta.json</code> entry and it sorts last with a title generated from its filename. Nothing checks that <code>index.md</code> and <code>overview.md</code> agree, so compare them by eye. If the content outgrows the skill, a fifth file, a human guide under <code>guides/</code>, holds the detail and the skill links it.</p><h2 id="writing-the-skill-file" tabindex="-1">Writing the skill file <a class="header-anchor" href="#writing-the-skill-file" aria-label="Permalink to “Writing the skill file”">​</a></h2><ul><li><strong>No YAML frontmatter.</strong> The package README explains why: downstream tooling adapts these files into tool-specific formats (Claude skills, Cursor rules, Copilot instructions) and adds its own frontmatter, so ours would collide. Title and ordering live in <code>_meta.json</code> instead.</li><li><strong>Open with an H1 and the trigger.</strong> The file starts with an H1 matching the title you give it in <code>_meta.json</code>. The first sentence under it is &quot;Use this skill whenever...&quot; followed by the situation, so an agent that landed here from the table can confirm it is in the right place. Because a skill has no frontmatter, its entry in the docs site&#39;s <code>llms.txt</code> is the H1 alone, with no description, so the H1 must say what the skill does.</li><li><strong>Then <code>## Steps</code></strong>, numbered, each one an action the agent can take. Put the reason for a rule in the step that states it. Existing skills such as <a href="/pr-preview/pr-11217/skills/contributors/start-in-a-fresh-worktree">Start in a Fresh Worktree</a> and <a href="/pr-preview/pr-11217/skills/contributors/keep-commits-human-authored">Keep Commits Human-Authored</a> are the house style.</li><li><strong>Link, don&#39;t restate.</strong> If a human guide owns a rule, link the guide and its heading rather than copying the rule. A copied rule goes stale silently; a link fails the link checker.</li><li><strong>Stay tool-agnostic.</strong> Say &quot;ask the user&quot; and &quot;a fresh agent instance&quot;, not the name of one product&#39;s tool or command. The skill is read by several agents.</li><li><strong>Put angle brackets in code spans.</strong> VitePress compiles markdown to Vue, so a bare <code>&lt;thing&gt;</code> in prose is parsed as an element and fails the docs build.</li><li><strong>Cross-reference other skills at the moment their case arises.</strong> The index routes one row per task, so a link from inside a skill is the only way an agent discovers a second skill mid-task: a bug-fix skill that ends &quot;if this changed documented behavior, follow Write Documentation&quot; reaches agents the documentation row never will. Link at the step where the other skill becomes relevant, don&#39;t summarize it, and add the reciprocal link when the dependency runs both ways.</li><li><strong>Link paths.</strong> Other skills are linked relatively (<code>./other-skill.md</code>, or <code>../schemas/other-skill.md</code> across directories); guides are linked by site path (<code>/guides/contributing/...md</code>); anchors must match a real heading.</li><li><strong>Keep it short.</strong> If a skill needs more than about 100 lines, some of it belongs in a human guide that the skill links.</li></ul><h2 id="wiring-it-in" tabindex="-1">Wiring it in <a class="header-anchor" href="#wiring-it-in" aria-label="Permalink to “Wiring it in”">​</a></h2><p>In the skill&#39;s directory:</p><ol><li>Add a row to <code>index.md</code>: the situation in the first column, the filename with its <code>.md</code> extension in the second. Rows that apply to every session are listed first and called out below the table; put a task-specific skill after them.</li><li>Add the matching row to <code>overview.md</code>, same first column, with the second column as a link: <code>[Title](/skills/&lt;directory&gt;/your-skill.md)</code>.</li><li>In <code>_meta.json</code>, add the slug to <code>items</code> where it should sit in the sidebar, and add <code>&quot;your-skill&quot;: { &quot;title&quot;: &quot;Your Title&quot; }</code> under <code>files</code>.</li></ol><h2 id="publishing-and-drafts" tabindex="-1">Publishing and drafts <a class="header-anchor" href="#publishing-and-drafts" aria-label="Permalink to “Publishing and drafts”">​</a></h2><p>The skills directory is synced to <code>/skills</code> on the website like the other content roots (see <a href="./#how-the-docs-site-is-built">How the Docs Site Is Built</a>), with one difference: a page marked <code>draft</code> is removed from the site entirely rather than hidden from the sidebar. That is how each directory&#39;s agent-facing <code>index.md</code> stays off the website while <code>overview.md</code> is published in its place: the directory&#39;s <code>_meta.json</code> carries both <code>&quot;files&quot;: { &quot;index&quot;: { &quot;draft&quot;: true } }</code> and <code>&quot;webIndex&quot;: &quot;overview&quot;</code>. Agents read from disk, so <code>draft</code> has no effect on them.</p><h2 id="checking-your-work" tabindex="-1">Checking your work <a class="header-anchor" href="#checking-your-work" aria-label="Permalink to “Checking your work”">​</a></h2><ul><li><code>pnpm lint:docs</code> from the repo root checks every link and heading anchor in <code>skills/</code> along with the guides (see <a href="./#checking-links">Checking Links</a>).</li><li>Build the site as <a href="./#previewing-your-changes">Previewing Your Changes</a> describes and open <code>/skills/contributors/</code> to see the sidebar entry and rendered page.</li><li>Hand the skill file alone, not the index or the repo, to a fresh agent instance with a task it should cover, and check that it follows the steps to the right place and does not name a tool specific to one product.</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};